CREATE TABLE IF NOT EXISTS content_performance(id INTEGER PRIMARY KEY,platform TEXT NOT NULL,platform_content_id TEXT NOT NULL,content_id TEXT,published_at TEXT,caption TEXT,content_type TEXT,permalink TEXT,views INTEGER,reach INTEGER,engagements INTEGER,likes INTEGER,comments INTEGER,shares INTEGER,saves INTEGER,favorites INTEGER,avg_watch_seconds REAL,skip_rate REAL,completion_rate REAL,new_followers INTEGER,profile_visits INTEGER,website_clicks INTEGER,lead_submissions INTEGER,raw_json TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(platform,platform_content_id));
CREATE INDEX IF NOT EXISTS idx_content_id ON content_performance(content_id);CREATE INDEX IF NOT EXISTS idx_published ON content_performance(published_at);
CREATE TABLE IF NOT EXISTS conversion_events(id INTEGER PRIMARY KEY,content_id TEXT,event_type TEXT NOT NULL,source TEXT NOT NULL,event_id TEXT NOT NULL,revenue REAL DEFAULT 0,currency TEXT DEFAULT 'USD',occurred_at TEXT,raw_json TEXT,UNIQUE(source,event_id));
CREATE TABLE IF NOT EXISTS sync_runs(id INTEGER PRIMARY KEY,source TEXT,status TEXT,records INTEGER,details TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
